<?php
/** Verified paid consumption + explicit settlement review. No bank transfer integration. */
declare(strict_types=1);
function nspp_policy():array{$r=ns_doc('support:cash-policy');return array_replace(['enabled'=>false,'legalReviewed'=>false,'providerReviewed'=>false,'taxReviewed'=>false,'wonPerPoint'=>1,'reference'=>''],$r['data']??[]);}
function nspp_ready():bool{$p=nspp_policy();return $p['enabled']&&$p['legalReviewed']&&$p['providerReviewed']&&$p['taxReviewed']&&trim($p['reference'])!=='';}
function nspp_paid_source(array $p,string $owner):?array{if($p['po_rel_table']!=='noa_toss'||!preg_match('/^paid:([a-f0-9-]{36})$/D',$p['po_rel_action'],$m))return null;$r=ns_doc('toss:order:'.$m[1]);$d=$r['data']??[];if(($d['ownerId']??'')!==$owner||($d['mode']??'')!=='live'||empty($d['credited'])||($d['state']??'')!=='paid'||($d['paidReversed']??0)>0)return null;[$rel,$action]=ns_point_relation($m[1],'paid');if($p['po_rel_id']!==$rel||$p['po_rel_action']!==$action||(int)$p['po_point']!==($d['paidPoints']??null))return null;return ['order'=>$m[1],'pointId'=>(int)$p['po_id']];}
function nspp_snapshot(string $owner):array{static $supported=null;if($supported===null){$r=ns_one('SELECT COUNT(*) n FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='.ns_e(trim(ns_table('point_table'),'`'))." AND COLUMN_NAME='po_use_point'");$supported=(int)$r['n']===1;}if(!$supported)return [];$out=[];$q=ns_q('SELECT po_id,po_point,po_use_point,po_rel_table,po_rel_id,po_rel_action FROM '.ns_table('point_table').' WHERE mb_id='.ns_e($owner).' AND po_point>0 FOR UPDATE');while($p=sql_fetch_array($q)){$paid=nspp_paid_source($p,$owner);$out[(int)$p['po_id']]=['used'=>(int)$p['po_use_point'],'paid'=>$paid,'free'=>!$paid&&in_array($p['po_rel_table'],['noa_membership','noa_reward','noa_login'],true)||str_starts_with($p['po_rel_action'],'bonus:')];}return $out;}
function nspp_funding(array $before,array $after,int $amount):array{$paid=0;$free=0;$sources=[];foreach($after as $id=>$p){$used=max(0,$p['used']-($before[$id]['used']??$p['used']));if(!$used)continue;if($p['paid']){$paid+=$used;$sources[]=$p['paid']+['amount'=>$used];}elseif($p['free'])$free+=$used;}if($paid+$free>$amount)throw new RuntimeException('point_provenance_mismatch');return ['paid'=>$paid,'free'=>$free,'unverified'=>$amount-$paid-$free,'sources'=>$sources];}
function nspp_receipts(string $owner,bool $sent=false):array{$q=ns_q("SELECT doc_key,payload,revision FROM noa_documents WHERE kind='support_receipt' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.".($sent?'sender':'recipient')."'))=".ns_e($owner)." ORDER BY updated_at DESC");$out=[];while($r=sql_fetch_array($q)){$r['data']=json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);$r['revision']=(int)$r['revision'];$out[]=$r;}return $out;}
function nspp_eligible(array $d):int{if(!empty($d['refunded'])||!empty($d['settlementKey'])||!empty($d['refundRequested']))return 0;$sum=0;foreach($d['funding']['sources']??[] as $s){$o=ns_doc('toss:order:'.$s['order'])['data']??[];if(($o['state']??'')==='paid'&&($o['mode']??'')==='live'&&!empty($o['credited'])&&($o['paidReversed']??0)===0)$sum+=(int)$s['amount'];}return min((int)($d['funding']['paid']??0),$sum);}
function nspp_dashboard(string $owner):array{$base=nsp_dashboard($owner);$rows=nspp_receipts($owner);$month=(new DateTimeImmutable('first day of this month 00:00:00',new DateTimeZone('Asia/Seoul')))->getTimestamp();$metrics=['month'=>0,'paidPoints'=>0,'freePoints'=>0,'unverifiedPoints'=>0,'eligible'=>0,'refunded'=>0,'settled'=>0];$incoming=[];foreach($rows as $r){$d=$r['data'];$amount=$d['receipt']['amount'];if(!empty($d['refunded'])){$metrics['refunded']+=$amount;continue;}if($d['receipt']['at']>=$month)$metrics['month']+=$amount;$f=$d['funding']??['paid'=>0,'free'=>0,'unverified'=>$amount];$metrics['paidPoints']+=$f['paid'];$metrics['freePoints']+=$f['free'];$metrics['unverifiedPoints']+=$f['unverified'];$metrics['eligible']+=nspp_eligible($d);$incoming[]=$d['receipt']+['key'=>$r['doc_key'],'message'=>$d['message'],'funding'=>$f,'status'=>!empty($d['refundRequested'])?'환불 검토 중':(!empty($d['settlementKey'])?'정산 신청됨':'후원 완료')];}
 $sent=[];foreach(array_slice(nspp_receipts($owner,true),0,50)as $r){$d=$r['data'];$sent[]=$d['receipt']+['key'=>$r['doc_key'],'message'=>$d['message'],'status'=>!empty($d['refunded'])?'환불 완료':(!empty($d['refundRequested'])?'환불 검토 중':'후원 완료'),'refundAvailable'=>empty($d['refunded'])&&empty($d['settlementKey'])];}
 $profile=ns_doc('support:profile:'.hash('sha256',$owner))['data']??['kind'=>'personal','status'=>'unverified'];$base['items']=array_slice($incoming,0,50);return $base+['metrics'=>$metrics,'sent'=>$sent,'profile'=>$profile,'policy'=>nspp_policy(),'cashEnabled'=>nspp_ready()];}
function nspp_profile(string $owner,array $b):array{$kind=$b['kind']??'';if(!in_array($kind,['personal','business'],true))throw new InvalidArgumentException('invalid_settlement_kind');$note=trim((string)($b['note']??''));if(mb_strlen($note)>500)throw new InvalidArgumentException('invalid_profile');return ns_atomic($owner,false,function()use($owner,$kind,$note){$k='support:profile:'.hash('sha256',$owner);$r=ns_doc($k,true);$d=['owner'=>$owner,'kind'=>$kind,'note'=>$note,'status'=>'submitted','at'=>time()];ns_put($k,'support_profile',$d,$r['revision']??0,$owner);return $d;});}
function nspp_request(string $owner,string $id,string $kind):array{ns_order_key($id);if(!in_array($kind,['personal','business'],true))throw new InvalidArgumentException('invalid_settlement_kind');return ns_atomic($owner,false,function()use($owner,$id,$kind){$key='support:settlement:'.hash('sha256',$owner.'|'.$id);$old=ns_doc($key,true);if($old){if(($old['data']['kind']??'')!==$kind)throw new DomainException('request_conflict');return $old['data'];}if(!nspp_ready())throw new DomainException('cash_settlement_pending');$profile=ns_doc('support:profile:'.hash('sha256',$owner))['data']??[];if(($profile['status']??'')!=='verified'||($profile['kind']??'')!==$kind)throw new DomainException('identity_verification_required');$wallet=nsp_wallet($owner,true);$rows=nspp_receipts($owner);$gross=0;$keys=[];foreach($rows as $r){$value=nspp_eligible($r['data']);if($value){$gross+=$value;$keys[]=$r['doc_key'];}}if($gross<1)throw new DomainException('no_settlement_balance');$d=['id'=>$id,'owner'=>$owner,'kind'=>$kind,'gross'=>$gross,'status'=>'requested','at'=>time(),'receiptKeys'=>$keys,'profileReference'=>$profile['reference'],'policyReference'=>nspp_policy()['reference']];foreach($rows as $r)if(in_array($r['doc_key'],$keys,true)){$r['data']['settlementKey']=$key;ns_put($r['doc_key'],'support_receipt',$r['data'],$r['revision'],$owner);}$wallet['data']['reserved']+=$gross;ns_put($wallet['key'],'support_wallet',$wallet['data'],$wallet['revision'],$owner);ns_put($key,'support_settlement',$d,0,$owner);return $d;});}
function nspp_admin(string $actor):void{global $config;if($actor!==($config['cf_admin']??''))throw new DomainException('administrator_required');}
function nspp_policy_save(string $actor,array $b):array{nspp_admin($actor);$d=[];foreach(['enabled','legalReviewed','providerReviewed','taxReviewed']as $k){if(!is_bool($b[$k]??null))throw new InvalidArgumentException('invalid_policy');$d[$k]=$b[$k];}$d['wonPerPoint']=1;$d['reference']=trim((string)($b['reference']??''));if(mb_strlen($d['reference'])>300||($d['enabled']&&(!$d['legalReviewed']||!$d['providerReviewed']||!$d['taxReviewed']||$d['reference']==='')))throw new DomainException('settlement_review_required');return ns_atomic('support-policy',false,function()use($actor,$d){$r=ns_doc('support:cash-policy',true);ns_put('support:cash-policy','support_policy',$d,$r['revision']??0,$actor);return $d;});}
function nspp_profile_review(string $actor,array $b):array{nspp_admin($actor);$owner=(string)($b['owner']??'');$reference=trim((string)($b['reference']??''));if($reference===''||mb_strlen($reference)>200||!in_array($b['status']??'', ['verified','rejected'],true))throw new InvalidArgumentException('invalid_review');return ns_atomic($owner,false,function()use($actor,$owner,$reference,$b){$k='support:profile:'.hash('sha256',$owner);$r=ns_doc($k,true);if(!$r)throw new DomainException('request_unavailable');$d=array_replace($r['data'],['status'=>$b['status'],'reference'=>$reference,'reviewedBy'=>$actor,'reviewedAt'=>time()]);ns_put($k,'support_profile',$d,$r['revision'],$actor);return $d;});}
function nspp_review(string $actor,array $b):array{nspp_admin($actor);$key=(string)($b['key']??'');if(!preg_match('/^support:settlement:[a-f0-9]{64}$/D',$key))throw new InvalidArgumentException('invalid_review');$r=ns_doc($key);if(!$r)throw new DomainException('request_unavailable');$owner=$r['data']['owner'];$decision=$b['decision']??'';$reference=trim((string)($b['reference']??''));if(!in_array($decision,['hold','verified','approved','paid','rejected'],true)||$reference===''||mb_strlen($reference)>200)throw new InvalidArgumentException('invalid_review');return ns_atomic($owner,false,function()use($key,$owner,$actor,$decision,$reference,$b){$r=ns_doc($key,true);$d=$r['data'];if(in_array($d['status'],['paid','rejected'],true)){if($d['status']===$decision&&($d['reference']??'')===$reference)return $d;throw new DomainException('request_already_reviewed');}
 if(!empty($d['receiptKeys'])){foreach($d['receiptKeys']as $receiptKey){$v=ns_doc($receiptKey,true);if(!$v)throw new DomainException('receipt_verification_required');if(in_array($decision,['verified','approved','paid'],true)){if(!empty($v['data']['refunded'])||!empty($v['data']['refundRequested']))throw new DomainException('receipt_verification_required');$copy=$v['data'];unset($copy['settlementKey']);if(nspp_eligible($copy)<($v['data']['funding']['paid']??0))throw new DomainException('receipt_verification_required');}}}elseif($decision!=='rejected'&&$decision!=='hold')throw new DomainException('legacy_provenance_required');
 if($decision==='verified'&&!in_array($d['status'],['requested','hold'],true))throw new DomainException('invalid_review_stage');
 if($decision==='approved'){if($d['status']!=='verified'||!nspp_ready())throw new DomainException('invalid_review_stage');$tax=$b['taxWon']??null;$net=$b['net']??null;$classification=trim((string)($b['classification']??''));if(!is_int($tax)||!is_int($net)||$tax<0||$net<1||$net+$tax!==$d['gross']||$classification===''||mb_strlen($classification)>200)throw new InvalidArgumentException('invalid_net');$d['taxWon']=$tax;$d['net']=$net;$d['classification']=$classification;}
 if($decision==='paid'&&($d['status']!=='approved'||!nspp_ready()||($b['externalPaidConfirmed']??false)!==true))throw new DomainException('external_payment_confirmation_required');
 if(in_array($decision,['paid','rejected'],true)){$w=nsp_wallet($owner,true);if($w['data']['reserved']<$d['gross'])throw new RuntimeException('ledger_mismatch');$w['data']['reserved']-=$d['gross'];if($decision==='paid')$w['data']['paid']+=$d['gross'];ns_put($w['key'],'support_wallet',$w['data'],$w['revision'],$actor);if($decision==='rejected')foreach($d['receiptKeys']??[]as $receiptKey){$v=ns_doc($receiptKey,true);if(($v['data']['settlementKey']??'')===$key){unset($v['data']['settlementKey']);ns_put($receiptKey,'support_receipt',$v['data'],$v['revision'],$actor);}}}
 $d['status']=$decision;$d['reference']=$reference;$d['reviewedAt']=time();$d['reviewedBy']=$actor;ns_put($key,'support_settlement',$d,$r['revision'],$actor);return $d;});}
function nspp_refund_request(string $owner,string $key,string $reason):array{if(!preg_match('/^support:receipt:[a-f0-9]{64}$/D',$key)||trim($reason)===''||mb_strlen($reason)>1000)throw new InvalidArgumentException('invalid_refund');return ns_atomic($owner,false,function()use($owner,$key,$reason){$r=ns_doc($key,true);if(!$r||$r['data']['sender']!==$owner)throw new DomainException('request_unavailable');if(!empty($r['data']['settlementKey']))throw new DomainException('settlement_in_progress');if(!empty($r['data']['refunded']))return ['status'=>'refunded'];$r['data']['refundRequested']=['reason'=>$reason,'at'=>time()];ns_put($key,'support_receipt',$r['data'],$r['revision'],$owner);return ['status'=>'requested'];});}
function nspp_refund_review(string $actor,array $b):array{nspp_admin($actor);$key=(string)($b['key']??'');if(!preg_match('/^support:receipt:[a-f0-9]{64}$/D',$key)||!in_array($b['decision']??'', ['refunded','rejected'],true))throw new InvalidArgumentException('invalid_refund');$r=ns_doc($key);if(!$r)throw new DomainException('request_unavailable');$owner=$r['data']['sender'];return ns_atomic($owner,true,function()use($key,$owner,$actor,$b){$r=ns_doc($key,true);$d=$r['data'];if(!empty($d['refunded']))return ['status'=>'refunded'];if(empty($d['refundRequested'])||!empty($d['settlementKey']))throw new DomainException('refund_not_available');$reason=trim((string)($b['reference']??''));if($reason===''||mb_strlen($reason)>200)throw new InvalidArgumentException('invalid_review');if($b['decision']==='refunded'){$w=nsp_wallet($d['recipient'],true);$amount=$d['receipt']['amount'];if($w['data']['received']-$w['data']['reserved']-$w['data']['paid']<$amount)throw new DomainException('refund_not_available');[$rel,$act]=ns_point_relation($d['receipt']['id'],'refund');if(insert_point($owner,$amount,'크레이터 후원 환불','noa_support',$rel,$act)!==1)throw new RuntimeException('refund_failed');$check=ns_one('SELECT po_point FROM '.ns_table('point_table').' WHERE mb_id='.ns_e($owner)." AND po_rel_table='noa_support' AND po_rel_id=".ns_e($rel).' AND po_rel_action='.ns_e($act));if((int)($check['po_point']??0)!==$amount)throw new RuntimeException('refund_failed');$w['data']['received']-=$amount;$w['data']['count']=max(0,$w['data']['count']-1);ns_put($w['key'],'support_wallet',$w['data'],$w['revision'],$actor);$ck='support:count:'.hash('sha256',$d['entity']);$c=ns_doc($ck,true);if($c){$c['data']['count']=max(0,($c['data']['count']??0)-1);ns_put($ck,'support_count',$c['data'],$c['revision'],$actor);}$d['refunded']=['at'=>time(),'by'=>$actor,'reference'=>$reason];}else{$d['refundRejection']=['at'=>time(),'reference'=>$reason];}unset($d['refundRequested']);ns_put($key,'support_receipt',$d,$r['revision'],$actor);return ['status'=>$b['decision']];});}
function nspp_admin_queue():array{$out=['profiles'=>[],'refunds'=>[]];foreach(['profiles'=>'support_profile','refunds'=>'support_receipt']as $field=>$kind){$where=$field==='refunds'?" AND JSON_EXTRACT(payload,'$.refundRequested') IS NOT NULL":'';$q=ns_q('SELECT doc_key,payload FROM noa_documents WHERE kind='.ns_e($kind).$where.' ORDER BY updated_at DESC LIMIT 100');while($r=sql_fetch_array($q))$out[$field][]=['key'=>$r['doc_key']]+json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);}return $out;}
/** Account-scoped audit projection; excludes other members and payment provider identifiers. */
function nspp_detail(string $owner,string $key,bool $admin=false):array{
 if(!preg_match('/^support:(receipt|settlement):[a-f0-9]{64}$/D',$key))throw new InvalidArgumentException('invalid_review');$r=ns_doc($key);if(!$r)throw new DomainException('request_unavailable');$d=$r['data'];
 if($admin)nspp_admin($owner);elseif(!in_array($owner,[$d['owner']??'',$d['sender']??'',$d['recipient']??''],true))throw new DomainException('request_unavailable');
 $history=[];$q=ns_q('SELECT revision,payload FROM noa_document_history WHERE doc_key='.ns_e($key).' ORDER BY revision DESC LIMIT 100');while($v=sql_fetch_array($q)){$p=json_decode($v['payload'],true);$history[]=['revision'=>(int)$v['revision'],'status'=>$p['status']??(!empty($p['refunded'])?'refunded':(!empty($p['refundRequested'])?'refund_requested':(!empty($p['settlementKey'])?'settlement_requested':'supported'))),'at'=>$p['reviewedAt']??$p['refunded']['at']??$p['refundRequested']['at']??$p['at']??$p['receipt']['at']??0];}
 $receipt=$d['receipt']??null;if($receipt&&($d['sender']??'')!==$owner&&!$admin)unset($receipt['balance']);$out=['history'=>$history,'receipt'=>$receipt,'message'=>$d['message']??''];
 if(isset($d['funding']))$out['funding']=array_intersect_key($d['funding'],array_flip(['paid','free','unverified']));if(isset($d['gross']))$out['settlement']=array_intersect_key($d,array_flip(['id','kind','gross','status','at','taxWon','net','classification','reference','reviewedAt']));
 return $out;
}
